const data = $input.first().json;
const posts = data?.data?.children || [];
const topPosts = posts
  .filter(p => !p.data.stickied)
  .slice(0, 10)
  .map((p, i) => {
    const d = p.data;
    return `${i+1}. [Score: ${d.score}] ${d.title} (${d.num_comments} comments)`;
  })
  .join('\n');

return {
  json: {
    redditSummary: topPosts
  }
};

const redditData = $('Format Reddit Data').first().json.redditSummary || 'No Reddit data';

const hnRaw = $input.first().json;
const hnHits = hnRaw.hits || [];
const hnSummary = hnHits.slice(0, 10).map((h, i) => {
  return `${i+1}. [Points: ${h.points}] ${h.title} (${h.num_comments} comments) - ${h.url || 'https://news.ycombinator.com/item?id=' + h.objectID}`;
}).join('\n');

return {
  json: {
    redditSummary: redditData,
    hnSummary: hnSummary,
    combinedPrompt: `REDDIT TOP POSTS (r/technology):\n${redditData}\n\nHACKER NEWS FRONT PAGE:\n${hnSummary}`
  }
};

const data = $input.first().json;

return {
  json: {
    rawStory: data.combinedPrompt,
    redditSummary: data.redditSummary,
    hnSummary: data.hnSummary,
    timestamp: new Date().toISOString()
  }
};

const geminiResponse = $input.first().json;
let response = '';

try {
  response = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Could not extract text from Gemini response: ' + JSON.stringify(geminiResponse).substring(0, 300));
}

let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Could not parse script JSON from Gemini response: ' + response.substring(0, 200));
  }
}

function findScriptData(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.SCRIPT || obj.script) return obj;
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    if (val && typeof val === 'object' && !Array.isArray(val)) {
      if (val.SCRIPT || val.script) return val;
      for (const k2 of Object.keys(val)) {
        const v2 = val[k2];
        if (v2 && typeof v2 === 'object' && !Array.isArray(v2)) {
          if (v2.SCRIPT || v2.script) return v2;
        }
      }
    }
  }
  return null;
}

let data = findScriptData(parsed);

if (!data && (parsed.STORY_TITLE || parsed.story_title)) {
  throw new Error('Gemini returned story analysis format instead of script format. Keys: ' + Object.keys(parsed).join(', ') + '. Expected SCRIPT, TITLE, IMAGE_PROMPTS. Retry should fix this.');
}

if (!data) throw new Error('Could not find SCRIPT in response. Keys: ' + JSON.stringify(Object.keys(parsed)) + '. Full: ' + JSON.stringify(parsed).substring(0, 500));

const script = data.SCRIPT || data.script;
const title = data.TITLE || data.title;
const description = data.DESCRIPTION || data.description || '';
const tags = data.TAGS || data.tags || [];
const imagePrompts = data.IMAGE_PROMPTS || data.image_prompts || data.imagePrompts || [];

if (!script) throw new Error('SCRIPT field is empty');
if (!title) throw new Error('TITLE field is empty');
if (!Array.isArray(imagePrompts) || imagePrompts.length < 4) {
  throw new Error('Need at least 4 image prompts, got ' + (Array.isArray(imagePrompts) ? imagePrompts.length : 'non-array'));
}

const wordCount = script.split(/\s+/).length;
if (wordCount < 90) {
  throw new Error('Script too short: ' + wordCount + ' words (need ~120). Retry should fix this.');
}

return {
  json: {
    script: script,
    title: title,
    description: description,
    tags: Array.isArray(tags) ? tags : [],
    imagePrompts: imagePrompts,
    wordCount: wordCount,
    timestamp: new Date().toISOString()
  }
};

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const scriptData = $input.first().json;
const prompts = scriptData.imagePrompts || [];
if (prompts.length === 0) throw new Error('No image prompts found');

const tmpDir = '/tmp/n8n_sdxl_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const workflow = {
    '1': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'sd_xl_base_1.0.safetensors' } },
    '2': { class_type: 'CLIPTextEncode', inputs: { text: 'PLACEHOLDER', clip: ['1', 1] } },
    '3': { class_type: 'CLIPTextEncode', inputs: { text: 'blurry, low quality, distorted, ugly, worst quality, low resolution, jpeg artifacts, watermark, text, duplicate, oversaturated, flat lighting', clip: ['1', 1] } },
    '4': { class_type: 'EmptyLatentImage', inputs: { width: 768, height: 1344, batch_size: 1 } },
    '5': { class_type: 'KSampler', inputs: { model: ['1', 0], positive: ['2', 0], negative: ['3', 0], latent_image: ['4', 0], seed: 0, steps: 30, cfg: 7.5, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1.0 } },
    '6': { class_type: 'VAEDecode', inputs: { samples: ['5', 0], vae: ['1', 2] } },
    '7': { class_type: 'SaveImage', inputs: { filename_prefix: 'sdxl_n8n', images: ['6', 0] } }
  };

  const config = { prompts, workflow };
  fs.writeFileSync(path.join(tmpDir, 'config.json'), JSON.stringify(config));

  const script = [
    "const http = require('http');",
    "const fs = require('fs');",
    "const path = require('path');",
    "const tmpDir = process.argv[2];",
    "const config = JSON.parse(fs.readFileSync(path.join(tmpDir, 'config.json'), 'utf8'));",
    "const prompts = config.prompts;",
    "const WORKFLOW = config.workflow;",
    "const COMFYUI = 'http://host.docker.internal:8188';",
    "const sleep = ms => new Promise(r => setTimeout(r, ms));",
    "",
    "function httpReq(urlStr, opts) {",
    "  return new Promise((resolve, reject) => {",
    "    const u = new URL(urlStr);",
    "    const method = (opts&&opts.method)||'GET';",
    "    const headers = (opts&&opts.headers)||{};",
    "    const body = opts&&opts.body;",
    "    const tout = (opts&&opts.timeout)||120000;",
    "    const r = http.request({hostname:u.hostname,port:u.port||8188,path:u.pathname+u.search,method,headers:{'Content-Type':'application/json',...headers}}, res => {",
    "      const chunks=[];",
    "      res.on('data',c=>chunks.push(c));",
    "      res.on('end',()=>resolve({status:res.statusCode,body:Buffer.concat(chunks)}));",
    "    });",
    "    r.on('error',reject);",
    "    r.setTimeout(tout,()=>{r.destroy();reject(new Error('Timeout'));});",
    "    if(body)r.write(body);",
    "    r.end();",
    "  });",
    "}",
    "",
    "async function submitPrompt(wf, clientId) {",
    "  const payload = JSON.stringify({ prompt: wf, client_id: clientId });",
    "  const res = await httpReq(COMFYUI + '/prompt', { method: 'POST', body: payload });",
    "  if (res.status !== 200) throw new Error('Submit failed: HTTP ' + res.status + ' ' + res.body.toString().substring(0, 500));",
    "  return JSON.parse(res.body.toString()).prompt_id;",
    "}",
    "",
    "async function pollHistory(promptId, timeoutMs) {",
    "  const start = Date.now();",
    "  while (Date.now() - start < timeoutMs) {",
    "    const res = await httpReq(COMFYUI + '/history/' + promptId, { timeout: 10000 });",
    "    if (res.status === 200) {",
    "      const data = JSON.parse(res.body.toString());",
    "      if (data[promptId] && data[promptId].status && data[promptId].status.completed !== undefined) {",
    "        if (data[promptId].status.status_str === 'error') {",
    "          const err = data[promptId].status.messages.find(m => m[0] === 'execution_error');",
    "          throw new Error('ComfyUI error: ' + (err ? JSON.stringify(err[1]).substring(0, 300) : 'unknown'));",
    "        }",
    "        if (data[promptId].outputs && Object.keys(data[promptId].outputs).length > 0) return data[promptId];",
    "      }",
    "    }",
    "    await sleep(3000);",
    "  }",
    "  throw new Error('ComfyUI timeout after ' + (timeoutMs/1000) + 's for prompt ' + promptId);",
    "}",
    "",
    "async function downloadImage(filename, subfolder, type) {",
    "  const url = COMFYUI + '/view?filename=' + encodeURIComponent(filename) + '&subfolder=' + encodeURIComponent(subfolder||'') + '&type=' + encodeURIComponent(type||'output');",
    "  const res = await httpReq(url, { timeout: 30000 });",
    "  if (res.status !== 200) throw new Error('Download failed: HTTP ' + res.status);",
    "  return res.body;",
    "}",
    "",
    "async function generateImage(prompt, idx) {",
    "  const wf = JSON.parse(JSON.stringify(WORKFLOW));",
    "  wf['2'].inputs.text = prompt;",
    "  wf['5'].inputs.seed = Math.floor(Math.random() * 2147483647);",
    "  const clientId = 'n8n-sdxl-' + Date.now() + '-' + idx;",
    "  const promptId = await submitPrompt(wf, clientId);",
    "  process.stderr.write('  Submitted ' + promptId.substring(0, 8) + '...\\n');",
    "  const result = await pollHistory(promptId, 300000);",
    "  const imgInfo = result.outputs['7'].images[0];",
    "  const imgBuf = await downloadImage(imgInfo.filename, imgInfo.subfolder, imgInfo.type);",
    "  return imgBuf.toString('base64');",
    "}",
    "",
    "async function main() {",
    "  const results = [];",
    "  for (let i = 0; i < prompts.length; i++) {",
    "    process.stderr.write('Image ' + (i+1) + '/' + prompts.length + '\\n');",
    "    const b64 = await generateImage(prompts[i], i);",
    "    results.push(b64);",
    "    process.stderr.write('  Done (' + Math.round(b64.length/1024) + ' KB)\\n');",
    "  }",
    "  process.stdout.write(JSON.stringify({ images: results }));",
    "}",
    "main().catch(e => { process.stderr.write('FATAL: ' + e.message + '\\n'); process.exit(1); });"
  ];

  fs.writeFileSync(path.join(tmpDir, 'generate.js'), script.join('\n'));

  const output = await new Promise((resolve, reject) => {
    exec(
      `node "${path.join(tmpDir, 'generate.js')}" "${tmpDir}"`,
      { timeout: 900000, maxBuffer: 200 * 1024 * 1024 },
      (error, stdout, stderr) => {
        if (error) {
          const fm = (stderr||'').match(/FATAL: ([\s\S]+)/);
          const tail = (stderr||'').split('\n').filter(l=>l.trim()).slice(-5).join(' | ');
          reject(new Error(fm ? fm[1].trim() : tail || error.message));
        } else {
          resolve(stdout);
        }
      }
    );
  });

  const result = JSON.parse(output);

  return {
    json: {
      imageBase64Array: result.images,
      imageCount: result.images.length,
      script: scriptData.script,
      title: scriptData.title,
      description: scriptData.description,
      tags: scriptData.tags,
      imagePrompts: scriptData.imagePrompts
    }
  };
} finally {
  try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch(e) {}
}

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const animData = $('Animate Images (ComfyUI Hunyuan)').first().json;
const clips = animData.videoClipBase64Array || [];
const clipDurations = animData.clipDurations || [];
if (clips.length === 0) throw new Error('No video clips found from Animate Images');

const ttsResponse = $input.first().json;
let audioBase64 = '';
try {
  audioBase64 = ttsResponse.candidates[0].content.parts[0].inlineData.data;
} catch (e) {
  throw new Error('Could not extract audio from Gemini TTS response: ' + JSON.stringify(ttsResponse).substring(0, 300));
}

const tmpDir = '/tmp/n8n_compose_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const clipPaths = [];
  for (let i = 0; i < clips.length; i++) {
    const clipPath = path.join(tmpDir, `clip_${i}.mp4`);
    fs.writeFileSync(clipPath, Buffer.from(clips[i], 'base64'));
    clipPaths.push(clipPath);
  }

  const pcmPath = path.join(tmpDir, 'audio.pcm');
  const wavPath = path.join(tmpDir, 'audio.wav');
  fs.writeFileSync(pcmPath, Buffer.from(audioBase64, 'base64'));
  execSync(`ffmpeg -y -f s16le -ar 24000 -ac 1 -i "${pcmPath}" "${wavPath}"`, { timeout: 30000 });

  let audioDuration = 45;
  try {
    const info = execSync(`ffmpeg -i "${wavPath}" 2>&1 || true`, { timeout: 10000 }).toString();
    const m = info.match(/Duration: (\d+):(\d+):([\d.]+)/);
    if (m) audioDuration = parseInt(m[1]) * 3600 + parseInt(m[2]) * 60 + parseFloat(m[3]);
  } catch(e) {}

  const numClips = clips.length;
  const fadeDuration = 0.3;
  const targetClipDuration = (audioDuration + (numClips - 1) * fadeDuration) / numClips;

  const procPaths = [];
  for (let i = 0; i < numClips; i++) {
    const origDur = clipDurations[i] || 1.04;
    const speedFactor = origDur / targetClipDuration;
    const procPath = path.join(tmpDir, `proc_${i}.mp4`);
    const filter = [
      `scale=1080:1920:force_original_aspect_ratio=increase:flags=lanczos`,
      `crop=1080:1920`,
      `unsharp=luma_msize_x=3:luma_msize_y=3:luma_amount=0.8`,
      `eq=contrast=1.02:saturation=1.1`,
      `minterpolate=fps=60:mi_mode=mci:mc_mode=aobmc:me_mode=bidir:vsbmc=1`,
      `setpts=PTS/${speedFactor.toFixed(4)}`,
      `trim=duration=${(targetClipDuration + 0.05).toFixed(2)}`,
      `setpts=PTS-STARTPTS`,
      `fps=30`
    ].join(',');
    execSync(
      `ffmpeg -y -i "${clipPaths[i]}" -vf "${filter}" -c:v libx264 -preset fast -crf 18 -pix_fmt yuv420p "${procPath}"`,
      { maxBuffer: 100 * 1024 * 1024, timeout: 300000 }
    );
    procPaths.push(procPath);
  }

  const inputArgs = procPaths.map(p => `-i "${p}"`).join(' ') + ` -i "${wavPath}"`;
  const xfadeParts = [];
  let lastLabel = '0:v';
  let offset = targetClipDuration - fadeDuration;
  for (let i = 1; i < numClips; i++) {
    const outLabel = i < numClips - 1 ? `t${i}` : 'vout';
    xfadeParts.push(
      `[${lastLabel}][${i}:v]xfade=transition=fade:duration=${fadeDuration}:offset=${offset.toFixed(2)}[${outLabel}]`
    );
    lastLabel = outLabel;
    offset += targetClipDuration - fadeDuration;
  }

  const outputPath = path.join(tmpDir, 'output.mp4');
  const cmd = `ffmpeg ${inputArgs} -filter_complex "${xfadeParts.join('; ')}" -map "[vout]" -map ${numClips}:a ` +
    `-c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p -c:a aac -b:a 192k -shortest -y "${outputPath}"`;
  execSync(cmd, { maxBuffer: 500 * 1024 * 1024, timeout: 600000 });

  const videoBuffer = fs.readFileSync(outputPath);
  return {
    json: { videoGenerated: true, duration: audioDuration, numClips, targetClipDuration },
    binary: {
      video: {
        data: videoBuffer.toString('base64'),
        mimeType: 'video/mp4',
        fileName: 'youtube_short.mp4'
      }
    }
  };
} finally {
  try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch(e) {}
}

const scriptData = $('Parse Script JSON').first().json;

const title = (scriptData.title || 'Tech News Today') + ' #Shorts';
const description = (scriptData.description || '') + '\n\n#Shorts #TechNews #AI #Technology';
const tags = scriptData.tags || ['tech', 'news', 'AI', 'shorts'];

const finalTitle = title.length > 100 ? title.substring(0, 97) + '...' : title;

return {
  json: {
    title: finalTitle,
    description: description,
    tags: tags,
    categoryId: '28',
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  },
  binary: $input.first().binary
};

const playlistItem = $input.first().json;
const videoId = playlistItem.contentDetails?.videoId ||
                playlistItem.snippet?.resourceId?.videoId ||
                'unknown';
const videoUrl = `https://youtube.com/shorts/${videoId}`;
const title = playlistItem.snippet?.title || '';

return {
  json: {
    success: true,
    message: 'YouTube Short published successfully!',
    videoUrl: videoUrl,
    videoId: videoId,
    title: title,
    uploadTime: new Date().toISOString()
  }
};

const fs = require('fs');
const path = require('path');

const item = $input.first();
const binary = item.binary;
const data = item.json;

// Pull metadata — comes from animateImages node output
const title = data.title || 'Untitled';
const script = data.script || '';
const description = data.description || '';
const tags = data.tags || [];

// Sanitize title for folder name: keep alphanumeric, spaces→underscores, limit length
const sanitized = title
  .replace(/[^a-zA-Z0-9 _-]/g, '')
  .trim()
  .replace(/\s+/g, '_')
  .substring(0, 80);

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
const folderName = timestamp + '_' + sanitized;
const basePath = '/home/node/videos/' + folderName;

fs.mkdirSync(basePath, { recursive: true });

// Write video file
const videoBuffer = Buffer.from(binary.video.data, 'base64');
fs.writeFileSync(path.join(basePath, 'video.mp4'), videoBuffer);

// Build YouTube hashtags from tags
const ytHashtags = (Array.isArray(tags) ? tags : []).map(t => '#' + t.replace(/[^a-zA-Z0-9]/g, '')).join(' ');

// Build Instagram caption (no #Shorts, add emojis + tech hashtags)
const instaHashtags = [
  '#TechNews', '#AI', '#Technology', '#Innovation', '#Tech',
  '#MachineLearning', '#ArtificialIntelligence', '#Future', '#Science',
  '#Programming', '#Software', '#Digital', '#NewTech', '#TechTrends',
  '#Startup', '#Engineering', '#DataScience', '#Robotics', '#CloudComputing',
  '#Cybersecurity'
].join(' ');

const cleanTitle = title.replace(/#Shorts/gi, '').trim();
const ytTitle = cleanTitle + ' #Shorts';

const infoLines = [
  '═══════════════════════════════════════',
  '  VIDEO UPLOAD INFO',
  '═══════════════════════════════════════',
  '',
  'Generated: ' + new Date().toISOString(),
  'Folder:    ' + folderName,
  '',
  '───────────────────────────────────────',
  '  SCRIPT (voiceover text)',
  '───────────────────────────────────────',
  script,
  '',
  '───────────────────────────────────────',
  '  YOUTUBE UPLOAD',
  '───────────────────────────────────────',
  'Title:',
  ytTitle,
  '',
  'Description:',
  description,
  '',
  'Tags (comma-separated):',
  (Array.isArray(tags) ? tags : []).join(', '),
  '',
  'Hashtags (add to description):',
  ytHashtags,
  '',
  'Category: Science & Technology (ID 28)',
  'Privacy:  Public (change to Unlisted for testing)',
  'Made for kids: No',
  '',
  '───────────────────────────────────────',
  '  INSTAGRAM REELS UPLOAD',
  '───────────────────────────────────────',
  'Caption (copy-paste entire block below):',
  '---',
  cleanTitle + ' \uD83D\uDD25',
  '',
  description.split('\n')[0],
  '',
  instaHashtags,
  '---',
  '',
  'Share as: Reels',
  'Cover frame: first frame or custom thumbnail',
  '',
  '═══════════════════════════════════════',
];

fs.writeFileSync(path.join(basePath, 'upload-info.txt'), infoLines.join('\n'), 'utf8');

return {
  json: { ...data, exportFolder: folderName, exportPath: basePath },
  binary: binary
};
